CREATE TABLE IF NOT EXISTS dim_city (city_id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, country TEXT NOT NULL DEFAULT 'India', latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS dim_station (station_id BIGSERIAL PRIMARY KEY, source_id TEXT NOT NULL UNIQUE, city_id BIGINT NOT NULL REFERENCES dim_city, name TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS dim_pollutant (pollutant_id BIGSERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, canonical_unit TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dim_date (date_id INTEGER PRIMARY KEY, date_value DATE NOT NULL UNIQUE, year INTEGER NOT NULL, month INTEGER NOT NULL, day INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS raw_api_response (raw_id BIGSERIAL PRIMARY KEY, source TEXT NOT NULL, city TEXT NOT NULL, retrieved_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS rejected_record (rejected_id BIGSERIAL PRIMARY KEY, source TEXT NOT NULL, city TEXT, rejected_at TIMESTAMPTZ NOT NULL, reason TEXT NOT NULL, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS pipeline_run (run_id UUID PRIMARY KEY, started_at TIMESTAMPTZ NOT NULL, finished_at TIMESTAMPTZ, status TEXT NOT NULL, extracted INTEGER NOT NULL DEFAULT 0, transformed INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0, duplicates INTEGER NOT NULL DEFAULT 0, errors JSONB NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS city_watermark (city TEXT NOT NULL, source TEXT NOT NULL, watermark TIMESTAMPTZ NOT NULL, PRIMARY KEY(city, source));
CREATE TABLE IF NOT EXISTS fact_air_quality (air_quality_id BIGSERIAL PRIMARY KEY, source_id TEXT NOT NULL, station_id BIGINT NOT NULL REFERENCES dim_station, city_id BIGINT NOT NULL REFERENCES dim_city, pollutant_id BIGINT NOT NULL REFERENCES dim_pollutant, observed_at TIMESTAMPTZ NOT NULL, value DOUBLE PRECISION NOT NULL CHECK(value >= 0), unit TEXT NOT NULL, anomaly BOOLEAN NOT NULL DEFAULT FALSE, raw_id BIGINT REFERENCES raw_api_response, CONSTRAINT uq_fact_air_quality_source_pollutant_time UNIQUE(source_id, pollutant_id, observed_at));
CREATE TABLE IF NOT EXISTS fact_weather (weather_id BIGSERIAL PRIMARY KEY, city_id BIGINT NOT NULL REFERENCES dim_city, observed_at TIMESTAMPTZ NOT NULL, temperature_c DOUBLE PRECISION, relative_humidity DOUBLE PRECISION, wind_speed_kmh DOUBLE PRECISION, precipitation_mm DOUBLE PRECISION, weather_code INTEGER, raw_id BIGINT REFERENCES raw_api_response, UNIQUE(city_id, observed_at));
CREATE INDEX IF NOT EXISTS ix_air_city_time ON fact_air_quality(city_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS ix_air_pollutant_time ON fact_air_quality(pollutant_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS ix_weather_city_time ON fact_weather(city_id, observed_at DESC);
ALTER TABLE dim_station ALTER COLUMN source_id TYPE TEXT USING source_id::text;
ALTER TABLE fact_air_quality DROP CONSTRAINT IF EXISTS fact_air_quality_source_id_observed_at_key;
ALTER TABLE fact_air_quality ALTER COLUMN source_id TYPE TEXT USING source_id::text;
ALTER TABLE fact_air_quality DROP CONSTRAINT IF EXISTS fact_air_quality_source_id_pollutant_id_observed_at_key;
ALTER TABLE fact_air_quality DROP CONSTRAINT IF EXISTS uq_fact_air_quality_source_pollutant_time;
ALTER TABLE fact_air_quality ADD CONSTRAINT uq_fact_air_quality_source_pollutant_time UNIQUE(source_id, pollutant_id, observed_at);
